import type {
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error } from "./reservation";
import {
  decodeCanonicalDecimal,
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeCanonicalDecimal,
  isId,
  isQuantity,
  isRecord,
  isRevision,
  isUnits,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadResult =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId }
        : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function decodeReadEnvelope(value: unknown): ReadResult {
  if (!isRecord(value) || typeof value.ok !== "boolean") return { kind: "unavailable" };
  if (value.ok) {
    return Object.hasOwn(value, "value") && value.value !== null
      ? { kind: "found", value: value.value }
      : { kind: "unavailable" };
  }
  if (!isRecord(value.error) || typeof value.error.reason !== "string") {
    return { kind: "unavailable" };
  }
  return value.error.reason === "NO_SUCH_KEY" ? { kind: "missing" } : { kind: "unavailable" };
}

function providerStockToStock(row: ProviderBStockRow, requestedSku: string): Stock | undefined {
  const totalUnits = decodeCanonicalDecimal(row.onHandText);
  const reservedUnits = decodeCanonicalDecimal(row.heldText);
  const revision = decodeCanonicalDecimal(row.revisionText);
  if (row.itemKey !== requestedSku || totalUnits === undefined || reservedUnits === undefined ||
      revision === undefined || !isUnits(totalUnits) || !isUnits(reservedUnits) ||
      reservedUnits > totalUnits || !isRevision(revision)) {
    return undefined;
  }
  return { sku: row.itemKey, totalUnits, reservedUnits, revision };
}

function providerReservationToReservation(
  row: ProviderBReservationRow,
  requestedReservationId: string,
): Reservation | undefined {
  const quantity = decodeCanonicalDecimal(row.unitsText);
  if (row.bookingKey !== requestedReservationId || quantity === undefined ||
      !isId(row.itemKey) || !isQuantity(quantity)) {
    return undefined;
  }
  return { reservationId: row.bookingKey, sku: row.itemKey, quantity };
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

function availabilityResponse(stock: Stock): ServiceResponse {
  return {
    status: 200,
    body: {
      sku: stock.sku,
      totalUnits: stock.totalUnits,
      reservedUnits: stock.reservedUnits,
      availableUnits: stock.totalUnits - stock.reservedUnits,
    },
  };
}

function toStockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: encodeCanonicalDecimal(stock.totalUnits),
    heldText: encodeCanonicalDecimal(stock.reservedUnits),
    revisionText: encodeCanonicalDecimal(stock.revision),
  };
}

function toReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: encodeCanonicalDecimal(reservation.quantity),
  };
}

function toCommitBatch(stock: Stock, reservation: Reservation): ProviderBCommitBatch | undefined {
  const nextRevision = stock.revision + 1;
  if (!isRevision(nextRevision)) return undefined;
  const nextStock: Stock = {
    ...stock,
    reservedUnits: stock.reservedUnits + reservation.quantity,
    revision: nextRevision,
  };
  const reservationRow = toReservationRow(reservation);
  return {
    expectedRevisionText: encodeCanonicalDecimal(stock.revision),
    stockRow: toStockRow(nextStock),
    reservationRow,
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservationRow.bookingKey,
        itemKey: reservationRow.itemKey,
        unitsText: reservationRow.unitsText,
      },
    }],
  };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<Stock | "missing" | "unavailable"> {
  const result = decodeReadEnvelope(await storage.read({ collection: "inventory", key: sku }));
  if (result.kind !== "found") return result.kind;
  const row = decodeProviderBStockRow(result.value);
  if (row === undefined) return "unavailable";
  return providerStockToStock(row, sku) ?? "unavailable";
}

async function readReservation(
  storage: ProviderBStorage,
  reservationId: string,
): Promise<Reservation | "missing" | "unavailable"> {
  const result = decodeReadEnvelope(await storage.read({ collection: "reservations", key: reservationId }));
  if (result.kind !== "found") return result.kind;
  const row = decodeProviderBReservationRow(result.value);
  if (row === undefined) return "unavailable";
  return providerReservationToReservation(row, reservationId) ?? "unavailable";
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock === "missing") return error(404, "stock_not_found");
          if (stock === "unavailable") return error(500, "storage_unavailable");
          return availabilityResponse(stock);
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing === "missing"
            ? error(404, "reservation_not_found")
            : reservationResponse(200, existing);
        }
        if (existing !== "missing") {
          return existing.sku === command.sku && existing.quantity === command.quantity
            ? reservationResponse(200, existing)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock === "missing") return error(404, "stock_not_found");
        if (stock === "unavailable") return error(500, "storage_unavailable");
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const batch = toCommitBatch(stock, reservation);
        if (batch === undefined) return error(500, "storage_unavailable");
        const outcome = await storage.commitBatch(batch);
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

