import type { ProviderBReservationRow, ProviderBStockRow, Reservation, Stock } from "./types";

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export function isUnits(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) &&
    value >= 0 && value <= 1_000_000;
}

export function isQuantity(value: unknown): value is number {
  return isUnits(value) && value > 0;
}

export function isRevision(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function decodeStock(value: unknown): Stock | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits ||
      !isRevision(value.revision)) return undefined;
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
    revision: value.revision,
  };
}

export function decodeReservation(value: unknown): Reservation | undefined {
  if (!isRecord(value) || !isId(value.reservationId) ||
      !isId(value.sku) || !isQuantity(value.quantity)) return undefined;
  return {
    reservationId: value.reservationId,
    sku: value.sku,
    quantity: value.quantity,
  };
}

export type SnapshotRow = {
  sku: string;
  totalUnits: number;
  reservedUnits: number;
};

export function decodeSnapshotRow(value: unknown): SnapshotRow | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits) {
    return undefined;
  }
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
  };
}

export function decodeCanonicalDecimal(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^(0|[1-9][0-9]*)$/.test(value)) return undefined;
  const decoded = Number(value);
  return Number.isSafeInteger(decoded) ? decoded : undefined;
}

export function encodeCanonicalDecimal(value: number): string {
  return String(value);
}

export function decodeProviderBStockRow(value: unknown): ProviderBStockRow | undefined {
  if (!isRecord(value) || !isId(value.itemKey) ||
      typeof value.onHandText !== "string" || typeof value.heldText !== "string" ||
      typeof value.revisionText !== "string" ||
      decodeCanonicalDecimal(value.onHandText) === undefined ||
      decodeCanonicalDecimal(value.heldText) === undefined ||
      decodeCanonicalDecimal(value.revisionText) === undefined) {
    return undefined;
  }
  return {
    itemKey: value.itemKey,
    onHandText: value.onHandText,
    heldText: value.heldText,
    revisionText: value.revisionText,
  };
}

export function decodeProviderBReservationRow(value: unknown): ProviderBReservationRow | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || !isId(value.itemKey) ||
      typeof value.unitsText !== "string" ||
      decodeCanonicalDecimal(value.unitsText) === undefined) {
    return undefined;
  }
  return {
    bookingKey: value.bookingKey,
    itemKey: value.itemKey,
    unitsText: value.unitsText,
  };
}
